    {
      "name": "ProbabilityTheory.variance",
      "type": " {Ω : Type u_1} {mΩ : MeasurableSpace Ω} (X : Ω → ℝ) (μ : MeasureTheory.Measure Ω) : ℝ",
      "module": "Mathlib.Probability.Moments.Variance"
    },
    {
      "name": "ProbabilityTheory.variance_nonneg",
      "type": " {Ω : Type u_1} {mΩ : MeasurableSpace Ω} (X : Ω → ℝ) (μ : MeasureTheory.Measure Ω) : 0 ≤ ProbabilityTheory.variance X μ",
      "module": "Mathlib.Probability.Moments.Variance"
    },
    {
      "name": "ProbabilityTheory.variance_fun_neg",
      "type": " {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {X : Ω → ℝ} {μ : MeasureTheory.Measure Ω} : ProbabilityTheory.variance (fun ω => -X ω) μ = ProbabilityTheory.variance X μ",
      "module": "Mathlib.Probability.Moments.Variance"
    },
    {
      "name": "ProbabilityTheory.covariance_self",
      "type": " {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {X : Ω → ℝ} (hX : AEMeasurable X μ) : ProbabilityTheory.covariance X X μ = ProbabilityTheory.variance X μ",
      "module": "Mathlib.Probability.Moments.Variance"
    },
    {
      "name": "ProbabilityTheory.variance_neg",
      "type": " {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {X : Ω → ℝ} {μ : MeasureTheory.Measure Ω} : ProbabilityTheory.variance (-X) μ = ProbabilityTheory.variance X μ",
      "module": "Mathlib.Probability.Moments.Variance"
    }
  ]
}

{
  "items": [
    {
      "name": "ProbabilityTheory.meas_ge_le_variance_div_sq",
      "module_name": "Mathlib.Probability.Moments.Variance",
      "kind": "theorem",
      "type": "∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} [MeasureTheory.IsFiniteMeasure μ] {X : Ω → ℝ},\n  MeasureTheory.MemLp X 2 μ →\n    ∀ {c : ℝ}, 0 < c → μ {ω | c ≤ |X ω - ∫ (x : Ω), X x ∂μ|} ≤ ENNReal.ofReal (ProbabilityTheory.variance X μ / c ^ 2)"
    },
    {
      "name": "ProbabilityTheory.meas_ge_le_evariance_div_sq",
      "module_name": "Mathlib.Probability.Moments.Variance",
      "kind": "theorem",
      "type": "∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {X : Ω → ℝ},\n  MeasureTheory.AEStronglyMeasurable X μ →\n    ∀ {c : NNReal}, c ≠ 0 → μ {ω | ↑c ≤ |X ω - ∫ (x : Ω), X x ∂μ|} ≤ ProbabilityTheory.evariance X μ / ↑c ^ 2"
    },
    {
      "name": "ProbabilityTheory.IndepFun.variance_add",
      "module_name": "Mathlib.Probability.Moments.Variance",
      "kind": "theorem",
      "type": "∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {X Y : Ω → ℝ},\n  MeasureTheory.MemLp X 2 μ →\n    MeasureTheory.MemLp Y 2 μ →\n      ProbabilityTheory.IndepFun X Y μ →\n        ProbabilityTheory.variance (X + Y) μ = ProbabilityTheory.variance X μ + ProbabilityTheory.variance Y μ"
    },
    {
      "name": "ProbabilityTheory.IndepFun.variance_sum",
      "module_name": "Mathlib.Probability.Moments.Variance",
      "kind": "theorem",
      "type": "∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {ι : Type u_3} {X : ι → Ω → ℝ} {s : Finset ι},\n  (∀ i ∈ s, MeasureTheory.MemLp (X i) 2 μ) →\n    ((↑s).Pairwise fun i j => ProbabilityTheory.IndepFun (X i) (X j) μ) →\n      ProbabilityTheory.variance (∑ i ∈ s, X i) μ = ∑ i ∈ s, ProbabilityTheory.variance (X i) μ"
    },
    {
      "name": "ProbabilityTheory.IndepFun.variance_fun_add",
      "module_name": "Mathlib.Probability.Moments.Variance",
      "kind": "theorem",
      "type": "∀ {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {X Y : Ω → ℝ},\n  MeasureTheory.MemLp X 2 μ →\n    MeasureTheory.MemLp Y 2 μ →\n      ProbabilityTheory.IndepFun X Y μ →\n        ProbabilityTheory.variance (fun ω => X ω + Y ω) μ =\n          ProbabilityTheory.variance X μ + ProbabilityTheory.variance Y μ"
    }
  ]
}
